// Drives the desktop dashboard and pairing window.
const { invoke } = window.__TAURI__.core;
const statusEl = document.getElementById("status");
const statePill = document.getElementById("state-pill");
const stateLabel = document.getElementById("state-label");
const timerMeta = document.getElementById("timer-meta");
const progressFill = document.getElementById("progress-fill");
const callNote = document.getElementById("call-note");
const pauseBtn = document.getElementById("toggle-pause");
const testBtn = document.getElementById("test-buzz");

function showFeedback(msg) {
  statusEl.textContent = msg;
}

async function refreshStatus() {
  try {
    const s = await invoke("app_status");
    const targetMin = Math.max(1, Math.round(s.break_after_secs / 60));
    const pct = Math.min(100, Math.round((s.sitting_secs / Math.max(1, s.break_after_secs)) * 100));
    progressFill.style.width = `${pct}%`;

    if (s.break_after_secs < 120) {
      timerMeta.textContent = `${s.sitting_secs} / ${s.break_after_secs} s`;
    } else {
      timerMeta.textContent = `${s.sitting_minutes} / ${targetMin} min`;
    }

    if (s.paused) {
      statePill.className = "pill pill-paused";
      stateLabel.textContent = "Paused";
      pauseBtn.textContent = "Resume timer";
      callNote.hidden = true;
    } else if (s.call_app) {
      statePill.className = "pill pill-hold";
      stateLabel.textContent = `In call · ${s.call_app}`;
      pauseBtn.textContent = "Pause timer";
      callNote.hidden = false;
      callNote.textContent = `Microphone in use by ${s.call_app} — buzzes are held until 30 s after the call ends.`;
    } else {
      statePill.className = "pill pill-active";
      stateLabel.textContent = "Active · Sitting tracker";
      pauseBtn.textContent = "Pause timer";
      callNote.hidden = true;
    }
  } catch (_) {}
}

async function render() {
  const info = await invoke("pairing_info");
  // The SVG is generated by our own Rust code, never from user or network input.
  document.getElementById("qr").innerHTML = info.qr_svg;
  document.getElementById("code").value = info.code;

  document.getElementById("copy").addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(info.code);
      showFeedback("Pairing code copied to clipboard.");
    } catch (_) {
      showFeedback("Select the code above and press Ctrl+C.");
    }
  });

  testBtn.addEventListener("click", async () => {
    await invoke("send_test_buzz");
    showFeedback("Test buzz sent — check your phone.");
  });

  pauseBtn.addEventListener("click", async () => {
    await invoke("toggle_pause");
    await refreshStatus();
  });

  await refreshStatus();
  setInterval(refreshStatus, 2000);
  await invoke("pairing_rendered", { qrShown: document.querySelector("#qr svg") !== null });
}

render().catch((err) => {
  showFeedback("Couldn't load pairing info: " + err);
});
